var e={имя:`Личный бренд`,лид:`Создаём авторитетов и экспертов в любой нише: бизнес, услуги, политика, культура, творчество, развлечения.`,значок:`/media/icons/lb.svg`,направление:`reputaciy`,титул:`Продвижение личного бренда – Social Stars`,описание:`Создаём авторитетов и экспертов в любой нише: бизнес, услуги, политика, культура, творчество, развлечения.`,вкладка:2,блоки:[{вид:`beforemore`,имя:`Что мы делаем?`,слева:[{вид:`абзац`,строки:[`Особенность нашего агентства - интересная история. Истоки Social Stars берут начало в те времена, когда в России еще никто не знал про блогеров.`,`Максим Петренчук, сооснователь Social Stars, в 11 классе создал самый популярный сайт в стране по игре Warcraft. В университете он познакомился с Павлом Дуровым, разработчиком ВКонтакте. Петренчук фигурирует в качестве персонажа в книге “Код Дурова” и в фильме “Дуров”. В 2008 году при поддержке Дурова был создан журнал ВКУРСЕ - первое СМИ о знаменитых людях в Интернете. Идеологом проекта выступил лично Дуров.`]}],справа:[{вид:`абзац`,строки:[`Мы строим личный бренд под ключ:`]},{вид:`список`,пункты:[`продумываем стратегию.`,`готовим котнент и разрабатываем креатив.`,`осуществляем продвижение.`,`создаём аккаунты с тысячами и миллионами подписчиков.`,`продвигаем эксперта на выступления.`,`организовываем эффективный нетворкинг.`,`пишем колонки.`]},{вид:`абзац`,строки:[`Основная цель личного бренда — не тщеславие, а привлечение новых клиентов и инвестиций.`]}]},{вид:`more`,имя:`Преимущества`,колонки:[`Лучшее агентство по личному бренду в России.`,`Сочетаем SMM, PR, ORM.`,`Делаем публикации в СМИ tier-1.`,`Создаем из предпринимателей звезд.`]},{вид:`blok-approach`,имя:`Наш подход:`,карточки:[{имя:`Стратегия`,строки:[`Составляли концепции для развития самых разных персон в Интернете - от Сергея Жукова до Екатерины Лапшиной, от Владимира Жириновского до Марии Лапук.`]},{имя:`Продакшн`,строки:[`Организуем удаленный продакшн контента, снимаем все под ключ - видео, сторис, фото, пишем экспертные тексты.`]},{имя:`Делегирование`,строки:[`Берём на себя все проблемы по личному блогу. Не превращайте блог во вторую работу.`]},{имя:`Полный цикл`,строки:[`Создаём и упаковываем продукты, консультируем, выводим на мероприятия.`]}]},{вид:`statistika`,имя:`Цифры`,показатели:[{кадр:`/media/reputaciy/1.svg`,число:null,черта:!1,подпись:`Повышение стоимости услуг и товаров, которое обеспечивает сильный личный бренд владельца.`},{кадр:`/media/reputaciy/2.svg`,число:null,черта:!1,подпись:`В два раза снижаются затраты на PR, если эксперт имеет развитые социальные сети и прозрачную репутацию в блоге.`},{кадр:`/media/reputaciy/3.svg`,число:null,черта:!1,подпись:`Увеличение числа полезных знакомств и контактов через интернет.`}]}]},t={имя:`PR`,лид:`Работа с развитием PR и репутации, используя классические инструменты и новые медиа.`,значок:`/media/icons/pr.svg`,направление:`reputaciy`,титул:`PR - Social Stars`,описание:null,вкладка:2,блоки:[{вид:`beforemore`,имя:`Что мы делаем?`,слева:[{вид:`абзац`,строки:[`PR крайне важен для бизнеса, потому что помогает создавать и поддерживать положительный имидж компании в обществе, повышать доверие клиентов и партнеров. В эпоху социальных сетей PR по-прежнему остаётся актуальным, поскольку аудитория очень серьезно воспринимает публикации в медиа. Мы применяем как традиционные инструменты (СМИ, ТВ, выступления, мероприятия), так и новые форматы (Telegram-каналы, посевы, работа с блогерами).`]}],справа:[{вид:`абзац`,строки:[`Регулярная работа с PR поддерживает маркетинговые усилия, потому что любые инструменты продаж увеличивают эффективность, если в основе лежит мощный информационный повод или история успеха.`]}]},{вид:`more`,имя:`Преимущества`,колонки:[`От Forbes до “Москвички”.`,`Без пометки “реклама”.`,`KPI в договоре.`,`Повышаем бизнес-показатели.`]},{вид:`blok-approach`,имя:`Наш подход:`,карточки:[{имя:`Составление стратегии`,строки:[`На первом этапе мы разрабатываем ключевые смыслы, которые транслируем от лица заказчика в публичное пространство, определяем площадки и инструменты.`]},{имя:`Работа под ключ`,строки:[`Готовим все публикации под ключ: находим фактуру, сверяем данные, готовим материалы.`]},{имя:`Креативный подход`,строки:[`Имеем большой опыт в журналистике, поэтому можем интегрировать автора как в лайфстайл-материал, так и написать уникальную экспертную публикацию.`]},{имя:`Акцент в бизнес`,строки:[`Все пиар-инструменты отработаны на личном опыте, поэтому мы привязываем рост медийности к продажам, прибыли или конкретным метрикам. Не делаем “статьи ради статей”.`]}]},{вид:`statistika`,имя:`Цифры`,показатели:[{кадр:`/media/reputaciy/4.svg`,число:null,черта:!1,подпись:`Интерес людей к статьям и репортажам выше, чем к традиционной рекламе.`},{кадр:`/media/reputaciy/5.svg`,число:null,черта:!1,подпись:`На столько снижается стоимость привлечения клиента через маркетинг, благодаря наличию сильного имиджа компании в медиа.`},{кадр:`/media/reputaciy/6.svg`,число:null,черта:!1,подпись:`В три раза быстрее растут стартапы, которые получают публичную оценку своей деятельности.`}]}]},n={имя:`Мониторинг и аналитика`,лид:`Мониторим Интернет, СМИ и социальные сети в поисках любой важной информации о бренде, способной повлиять на бизнес-процессы.`,значок:`/media/icons/monitoring.svg`,направление:`reputaciy`,титул:`Мониторинг и аналитика интернета и СМИ – Social Stars`,описание:`Мониторим Интернет, СМИ и социальные сети в поисках любой важной информации о бренде, способной повлиять на бизнес-процессы.`,вкладка:3,блоки:[{вид:`beforemore`,имя:`Что мы делаем?`,слева:[{вид:`абзац`,строки:[`Развитие бренда в социуме зависит от большого количества информационных фактов. Если вы следите за повесткой - ваш бизнес и товар защищены от критики и рисков, вы всегда знаете, как решить проблемы с потребителями. Нельзя доводить ситуацию до кризиса - как и в медицине, любую “болезнь” лучше вылечить превентивно.`]},{вид:`абзац`,строки:[`Помимо того, что аналитика влияет на позиции и качество продукта, она помогает улучшить рекламную кампанию, понять недовольство пользователей, узнать, какие ходы используют ваши конкуренты, а в каких местах вы теряете бюджет из-за неправильно выбранных площадок и смыслов.`]}],справа:[{вид:`абзац`,строки:[`Команда Social Stars состоит из опытных аналитиков, которые мониторят упоминания на любых площадках — в СМИ, социальных сетях, блогах. Мы предлагаем регулярные отчёты и оперативно реагируем в случае выявления проблемы. Анализируем не только бренд, но и страницы конкурентов или другие тематики по запросу.`]}]},{вид:`more`,имя:`Преимущества`,колонки:[`Партнеры Brand Analytics.`,`Работаем 24/7.`,`Опыт работы с государством.`,`Анализируем иностранные рынки.`]},{вид:`blok-approach`,имя:`Наш подход:`,карточки:[{имя:`Выбор ключевых тем`,строки:[`Согласовываем с заказчиком семантическое ядро, на основе чего начинаем строить модель наблюдения.`]},{имя:`Управление площадками`,строки:[`Настраиваем необходимые фильтры, выбираем социальные сети и другие ресурсы.`]},{имя:`Форма отчетности`,строки:[`Определяем уровень детализации отчёта: анализ нарративов, выводы, предложения и формат работы с обратной связью.`]},{имя:`Реагирование`,строки:[`Моментально включаемся в решение любой проблемы, применяем информационные и креативные инструменты.`]}]},{вид:`statistika`,имя:`Цифры`,показатели:[{кадр:`/media/reputaciy/7.svg`,число:null,черта:!1,подпись:`В пять раз сокращаются затраты на “тушение пожара” в результате кризисных PR-ситуаций.`},{кадр:`/media/reputaciy/4.svg`,число:null,черта:!1,подпись:`Повышение эффективности рекламных кампаний, которые применяют не только творческий подход, но и аналитику.`},{кадр:`/media/reputaciy/8.svg`,число:null,черта:!1,подпись:`Ускорение работы маркетингового отдела для принятия решений по выводу новых продуктов на рынок.`}]}]},r={имя:`ORM`,лид:`Партизанские методы работы с репутацией в Интернете, направленные на поддержание нужной точки зрения у потребителя или формирование повестки.`,значок:`/media/icons/orm.svg`,направление:`reputaciy`,титул:`ORM - Social Stars`,описание:null,вкладка:1,блоки:[{вид:`beforemore`,имя:`Что мы делаем?`,слева:[{вид:`абзац`,строки:[`Согласно статистике исследовательских компаний, около 72% потребителей перед принятием решения обращают внимание на отзывы и другой пользовательский контент.`]},{вид:`абзац`,строки:[`Все больше потребителей и клиентов доверяет не официальным материалам, пресс-релизам или даже обзорам блогерам, а “прямой информации”. Речь идет про оценки, комментарии, дискуссии, публикации в топе, “острова контента” и так далее.`]},{вид:`абзац`,строки:[`Увеличение позитивных упоминаний приводит к тому, что человек меняет свою точку зрения, даже не осознавая, что на его выбор повлияли рекламщики или профессионалы.`]}],справа:[{вид:`абзац`,строки:[`Подход ORM работает, потому что мы лучше воспринимаем данные, если считаем, что они получены от похожих на нас людей, оказавшихся в одинаковой ситуации выбора. Например, клиент читает форум BMW и вдруг видит позитивный отклик от юриста из компании “Газпром” об опыте работы в российском гиганте. Конечно же, вряд ли в этот момент читатель догадывается, что ORM-специалист получил задачу на продвижение корпоративного HR-бренда.`]},{вид:`абзац`,строки:[`Усложение интернет-технологий все больше затрудняет поиск отличий между контактом с живым человеком и виртуальной анкетой. Подобные технологии используются не только в политике, но и в коммерческом секторе.`]}]},{вид:`more`,имя:`Преимущества`,колонки:[`Собственные IT-технологии.`,`Партизанские тактики.`,`Создаем аккаунты под задачи.`,`Количество аккаунтов в нашей базе - до 5 000.`]},{вид:`blok-approach`,имя:`Наш подход:`,карточки:[{имя:`Составление стратегии`,строки:[`В начале работы определяем параметры, которые влияют на аудиторию заказчика. Пример: «Вывод топ комментариев в отраслевых сообществах».`]},{имя:`Гибкий подход`,строки:[`Сочетаем PR, классические и теневые методы для достжения бизнес-результата.`]},{имя:`Только органика`,строки:[`Страницы, через которые мы воздействуем на общественное мнение, неотличимы от профилей реальных людей.`]},{имя:`Полный отчет`,строки:[`В наш отчет входят ссылки на все размещения. Если отзыв удаляется, мы компенсируем его в рамках договора.`]}]},{вид:`statistika`,имя:`Цифры`,показатели:[{кадр:`/media/reputaciy/9.svg`,число:null,черта:!1,подпись:`Зрителей ролика на видеохостингах обращают внимание на мнение в комментариях.`},{кадр:`/media/reputaciy/10.svg`,число:null,черта:!1,подпись:`Клиентов изучают агрегаторы отзывов и аналогичные платформы.`},{кадр:`/media/reputaciy/11.svg`,число:null,черта:!1,подпись:`Потребителей не имеют своего мнения и формируют его на основе чужого опыта в сети.`}]}]},i={имя:`SERM`,лид:`Управление репутацией в поисковых системах (SERM) помогает вашему бренду доминировать в поисковых запросах с нужными смыслами и информационной повесткой.`,значок:`/media/icons/serm.svg`,направление:`reputaciy`,титул:`SERM - Social Stars`,описание:null,вкладка:1,блоки:[{вид:`beforemore`,имя:`Что мы делаем?`,слева:[{вид:`абзац`,строки:[`Современные поисковые системы (Yandex, Google и другие) являются ключевым источником информации о человеке, компании, услуге или тренде.`]},{вид:`абзац`,строки:[`Почему это важно?`,`• Негативная выдача оказывает огромное влияние на бизнес, так как потребители, как правило, изучают только первые строки поисковой выдачи.`,`• Наличие провокационных или негативных материалов может не только испортить мнение клиента, но и убедить его отказаться от сделки.`]}],справа:[{вид:`абзац`,строки:[`Мы знаем, как работают алгоритмы социальных сетей и поисковых систем. Благодаря этому:`]},{вид:`абзац`,строки:[`• Выводим на первые строки позитивный контент.`,`• Устраняем негатив через статьи, посевы и инструменты с высоким уровнем ранжирования.`,`• Создаём репутацию с нуля для новых бизнесов, используя передовые методы.`]}]},{вид:`more`,имя:`Преимущества`,колонки:[`Инструменты, которых нет у других агентств.`,`Материалы удерживаются в выдаче длительное время.`,`Продумываем Tone of Voice под каждый материал.`,`Работаем с поисковыми системами на иностранных рынках.`]},{вид:`blok-approach`,имя:`Наш подход:`,карточки:[{имя:`Исследование поиска`,строки:[`Проводим точечную аналитику, выявляем слабые места, которые негативно влияют на бизнес-показатели.`]},{имя:`Долгосрочная стратегия`,строки:[`Создаём планы управления поисковой выдачей с акцентом на релевантные и эффективные материалы.`]},{имя:`Нет ограничений`,строки:[`База более 300 разных СМИ по категориям, готовых опубликовать практически любой материал в рамках законодательства.`]},{имя:`Используем PR`,строки:[`Знаем, в каких СМИ статьи первыми отображаются в поиске.`]}]},{вид:`statistika`,имя:`Цифры`,показатели:[{кадр:`/media/reputaciy/12.svg`,число:null,черта:!1,подпись:`Предпринимателей изучают поисковую выдачу перед знакомством с партнёрами или подрядчиками.`},{кадр:`/media/reputaciy/13.svg`,число:null,черта:!1,подпись:`Клиенты уходят от бизнеса с негативными отзывами в поиске.`},{кадр:`/media/reputaciy/14.svg`,число:null,черта:!1,подпись:`Опубликовано нами статей для клиентов на разных рынках.`}]}]},a={имя:`Антикризис`,лид:`Решаем критические ситуации в бизнесе, когда необходимо моментальное информационное вмешательство.`,значок:`/media/icons/orm.svg`,направление:`reputaciy`,титул:`Антикризис - Social Stars`,описание:null,вкладка:2,блоки:[{вид:`beforemore`,имя:`Что мы делаем?`,слева:[{вид:`абзац`,строки:[`Каждый человек или компания могут столкнуться с неприятной ситуацией, когда бизнес подвергается угрозе в результате серьезного прецедента или распространяющегося негатива.`]},{вид:`абзац`,строки:[`Это может включать:`,`• скандалы, связанные с продуктами или услугами;`,`• утечки данных;`,`• ошибки коммуникации;`,`• информационные атаки;`]},{вид:`абзац`,строки:[`Антикризис - серия мер, направленных на быстрое реагирование, чтобы решить проблему на корню. Каждая минута времени при решении подобного кейса критична, потому что ведет к убыткам или более серьезным последствиям.`]}],справа:[{вид:`абзац`,строки:[`Особенности антикризисного подхода:`,`• Заготовленные шаблоны и стратегии, применение инсайдерских ТГ-каналов, СМИ и большой базы лояльных лидеров мнений, адвокатов бренда.`,`• Опыт решения вопросов, требующих поддержки общественных институтов, GR, подписание NDA.`,`• Применяем ORM и другие партизанские технологии, работаем на опережение в ситуации, задействуем собственную большую базу комментаторов.`]}]},{вид:`more`,имя:`Преимущества`,колонки:[`Конфиденциальность: работаем через договоры NDA.`,`Собственная база экспертов: используем лидеров мнений для поддержки.`,`Умеем решать вопросы, связанные с государственными задачами.`,`Приступаем к работе буквально в первый час после поступления запроса.`]},{вид:`blok-approach`,имя:`Наш подход:`,карточки:[{имя:`Отвлечение фокуса`,строки:[`Перевод дискуссии в нейтральное или позитивное русло.`]},{имя:`Субъектный подход`,строки:[`Показывает, что негатив связан с неудачным опытом критика и не является ценным для общества.`]},{имя:`Хаотизация повестки`,строки:[`Внедрение в дискуссию специальных агентов, которые дестабилизируют упорядоченный процесс обсуждения.`]},{имя:`Вытеснение позитивом`,строки:[`Даем личное мнение людей, которые выступают адвокатами и дают возможность перестроить тему.`]}]},{вид:`statistika`,имя:`Цифры`,показатели:[{кадр:`/media/reputaciy/4.svg`,число:null,черта:!1,подпись:`Роль социальных сетей в распространении негативных информационных поводов.`},{кадр:`/media/reputaciy/15.svg`,число:null,черта:!1,подпись:`Столько прибыли может потерять компания в первый день кризиса без грамотного плана выхода из ситуации.`},{кадр:`/media/reputaciy/16.svg`,число:null,черта:!1,подпись:`Клиенты, которых можно сохранить, если в первый день были запущены антикризисные меры.`}]}]},o={имя:`Удаление информации`,лид:`Удаляем из интернета данные, которые могут повредить репутации и бизнесу, — быстро, надёжно, конфиденциально.`,значок:`/media/icons/delite.svg`,направление:`reputaciy`,титул:`Удаление информации - Social Stars`,описание:null,вкладка:1,блоки:[{вид:`beforemore`,имя:`Что мы делаем?`,слева:[{вид:`абзац`,строки:[`Существует мнение, что информация, опубликованная в интернете, остаётся там навсегда. На самом деле есть множество инструментов, которые позволяют удалить нежелательные сведения или материалы в СМИ.`]},{вид:`абзац`,строки:[`Удаление информации:`,`• защищает компанию от рисков информационных атак, чёрного PR;`,`• минимизирует репутационные и финансовые потери;`,`• предотвращает негативное влияние на бизнес.`]}],справа:[{вид:`абзац`,строки:[`Social Stars использует комплексный подход: от технического удаления контента и понимания алгоритмов соцсетей до юридических аспектов.`]}]},{вид:`more`,имя:`Преимущества`,колонки:[`Прописываем KPI в договоре.`,`Умеем договориться с противниками бренда.`,`Решаем задачи через официальные связи в социальных сетях.`,`Обеспечиваем защиту с правовой стороны.`]},{вид:`blok-approach`,имя:`Наш подход:`,карточки:[{имя:`Изучаем ситуацию`,строки:[`Анализируем решение, даем обратную связь заказчика, ставим четкие сроки и прогнозы для решения задачи.`]},{имя:`Мягкая сила`,строки:[`В отдельных случаях можно договориться с автором - применить метод “пряника”.`]},{имя:`Минимизация рисков`,строки:[`Вся работа ведется, анонимно, не включая заказчика в коммуникацию, сохраняя нейтралитет и репутацию.`]},{имя:`Технический подход`,строки:[`Если не удается полностью удалить контент, используем алгоритмы социальных сетей, включаем метод “кнута”.`]}]},{вид:`statistika`,имя:`Цифры`,показатели:[{кадр:`/media/reputaciy/17.svg`,число:null,черта:!1,подпись:`Клиентов отказываются от услуги после прочтения негативного отзыва.`},{кадр:`/media/reputaciy/18.svg`,число:null,черта:!1,подпись:`Среднее количество негативных отзывов о крупных компаниях в соцсетях ежедневно.`},{кадр:`/media/reputaciy/19.svg`,число:null,черта:!1,подпись:`Единиц контента, удалённых нашими специалистами за время работы агентства.`}]}]},s={имя:`Исследования`,лид:`Оптимизируем бюджеты на рекламу блогеров в российских и международных рекламных кампаниях (увеличение эффективности в 2-3 раза).`,значок:`/media/lider/1.svg`,направление:`lider`,титул:`Рекламные исследования – цены в агентстве Social Stars`,описание:`Оптимизируем бюджеты на рекламу блогеров в российских и международных рекламных кампаниях (увеличение эффективности в 2-3 раза).`,вкладка:3,блоки:[{вид:`beforemore`,имя:`Что мы делаем?`,слева:[{вид:`абзац`,строки:[`Лидеры мнений - это новый феномен XXI века, когда личные профили артистов или обычных людей сравнялись по своему медийному значению со СМИ. Social Stars стоят у истоков блогерской экспертизы. В 2014 году мы создали первое блогерское СМИ в России, а 2024 году основали Институт исследований лидеров мнений.`]}],справа:[{вид:`абзац`,строки:[`Современные продюсерские центры часто «продавливают» любимчиков для клиента, ссылаясь на успешные кейсы и медийное реноме. Цель исследований — дать возможность заказчику увидеть реальные цифры блогера, узнать статистику, которую не покажет официальная платформа. Мы находим новых привлекающих лиц.`]},{вид:`абзац`,строки:[`Вы хотите работать с правильными блогерами или найти амбассадора для вашего бренда? Исследования помогают сократить затраты на блогеров, а также понять, у кого из лидеров мнений пересекается аудитория, чтобы снизить издержки рекламной кампании.`]}]},{вид:`verticals`,имя:`Эффект, который дают исследования:`,карточки:[{имя:null,значок:`/media/lider/l1.svg`,строки:[`Data-driven подход в вопросе выбора лидера мнений всегда предпочтительнее, чем брать блогера “за громкое имя”.`]},{имя:null,значок:`/media/lider/l1.svg`,строки:[`Большее количество вариантов для креативной интеграции, основанной на понимании вкусах подписчиков конкретного ЛОМа.`]},{имя:null,значок:`/media/lider/l1.svg`,строки:[`Возможность выйти на новый рынок или даже в медиаполе другой страны, имея базовые представления о необходимой аудитории, не зная ничего о местных лидерах мнений.`]}]},{вид:`history`,имя:`Инструменты для реализации:`,текст:[`Каждое наше исследование мы привязываем к бизнес-целям — применяем научные методы для оптимизации бюджетов на маркетинг влияния.`],шаги:[{имя:`Методология`,текст:`Придумываем идею, как осуществить исследование в интересах заказчика. Просим заказчика заполнить бриф, указать блогеров или определить ЦА продукта/услуги.`},{имя:`Подбор блогеров`,текст:`Используем нашу платформу Follower AI, чтобы найти блогеров на основе выбранных интересов, либо - изучить определенного лидера мнений.`},{имя:`Кроссплатформенный подход`,текст:`Создаем лонг-лист для заказчика. На основе cost-оптимизации выделяем блогеров с релевантной аудиторией, подходящими интересами и лучшими ценами.`},{имя:`Креативное согласование`,текст:`После утверждения заказчиков связываемся с лучшими ЛОМ по списку и выстраиваем креативную стратегию.`}]}]},c={имя:`Креативные интеграции`,лид:`Встраиваем рекламу к блогерам так, чтобы это было эффективно, незаметно и эффектно одновременно.`,значок:`/media/lider/3.svg`,направление:`lider`,титул:`Рекламные интеграции у блогеров – цены в Social Stars`,описание:`Встраиваем рекламу к блогерам так, чтобы это было эффективно, незаметно и эффектно одновременно.`,вкладка:4,блоки:[{вид:`beforemore`,имя:`Что мы делаем?`,слева:[{вид:`абзац`,строки:[`На рынке распространена практика, когда рекламодатели путают формат блогеров и СМИ. Из-за этого они просто предоставляют лидерам мнений стандартную рекламу, что вызывает у аудитории раздражение: пост с коммерческой интеграцией не читают, а ролик сразу проматывают.`,`Мы придерживаемся иного подхода — делаем так, чтобы лидер мнений рекомендовал продукт или услугу искренне, на своём личном опыте.`]}],справа:[{вид:`абзац`,строки:[`Пользователи регулярно следят за блогерами и их выбором: от зубной пасты до автомобилей. Используем творческий подход и профессиональную режиссуру, чтобы ваш товар стал естественной частью их контента. Вместо абстрактных брендов ваши продукты займут место в их рекомендациях.`]}]},{вид:`verticals`,имя:`Эффект, который дают исследования:`,карточки:[{имя:null,значок:`/media/lider/l1.svg`,строки:[`Опыт с 2015 года.`,`Мы создавали рекламные сериалы на YouTube с участием топ-блогеров — Кати Клэп, Саши Спилберг, Иванага. Проекты подобного уровня тогда никто в России не делал.`]},{имя:null,значок:`/media/lider/l1.svg`,строки:[`Глубокое понимание.`,`Мы разбираемся в блогерах и искренне любим процесс. Выступаем в роли аналитиков, художников и практиков одновременно.`]},{имя:null,значок:`/media/lider/l1.svg`,строки:[`Индивидуальный подход.`,`Просим лидеров мнений участвовать в создании сценариев или идей для бренда. Это помогает достичь максимального результата.`]}]},{вид:`history`,имя:`Инструменты для реализации:`,текст:[`Сочетаем две противоположные вещи - умение делать индивидуальные авторские проекты и навык строить быстрые, автоматизированные процессы в производстве.`],шаги:[{имя:`Разработка концепции`,текст:`После заполнения брифа заказчиком мы выбираем блогеров и детально изучаем их контент.`},{имя:`Естественность`,текст:`Убедительно интегрируем продукт так, чтобы он выглядел органично. Например, странно, если блогер, пользующийся Samsung, внезапно начнёт рекламировать iPhone.`},{имя:`Договоренности с блогерами`,текст:`Мы выстраиваем отношения с лидерами мнений так, чтобы избежать перенасыщения аудитории рекламой. Они ценят искренний и интересный подход.`},{имя:`Аналитика`,текст:`Оцениваем эффективность креатива с использованием KPI и метрик, чтобы результат приносил пользу бренду.`}]}]},l={имя:`Brand-lift`,лид:`Делаем аналитику рекламных кампаний любой сложности с участием блогеров.`,значок:`/media/lider/4.svg`,направление:`lider`,титул:`Brand-lift - Social Stars`,описание:null,вкладка:3,блоки:[]},u={имя:`Sales-lift`,лид:`Интегрируем инструменты рекламных кампаний с использованием блогеров в CRM-систему заказчика для измерения результатов.`,значок:`/media/lider/5.svg`,направление:`lider`,титул:`Sales-lift - Social Stars`,описание:null,вкладка:3,блоки:[{вид:`beforemore`,имя:`Что мы делаем?`,слева:[{вид:`абзац`,строки:[`Измеряем влияние рекламы с участием лидеров мнений на продажи. Создаем комплексные маркетинговые и технические решения для оцифровки результата. Например, в рекламе задействуется десять разных блогеров. Подписчики какого лидера мнений больше всего купили товаров? Какие разделы сайта их больше всего интересовали, а какие они покинули? Какой средний чек потратил каждый фолловер? Аудитория какого блогера чаще всего оставляла брошенные корзины на сайте?`]}],справа:[{вид:`абзац`,строки:[`В концепции Sales-lift мы работаем не только с аналитикой продаж, но и со сложными метриками, такими как ARPU. Исследования sales-lift помогают и в офлайн-проектах. Например, кейс из реальной жизни: если вы разместили рекламу у блогера Торгового Центра, при помощи sales-lift вы узнаете, какие зоны клиенты посещали чаще и какие товары больше волновали вашу аудиторию.`]}]},{вид:`verticals`,имя:`Почему нужно внедрить sales-lift?`,карточки:[{имя:null,значок:`/media/lider/l1.svg`,строки:[`Узнаете не только то, сколько людей пришло к вам от рекламы, но и какие товары, услуги и разделы их интересовали больше всего.`]},{имя:null,значок:`/media/lider/l1.svg`,строки:[`Получите ценную аналитику, которая позволит доработать интерфейсы сайта, приложения, улучшить ценовую политику и так далее.`]},{имя:null,значок:`/media/lider/l1.svg`,строки:[`Прекратите бессмысленный слив бюджетов на блогеров с “имиджевыми размещениями”, используя аналитические данные.`]}]},{вид:`history`,имя:`Инструменты для реализации:`,текст:[`Оцифровка маркетинга дает понимание, как ваша реклама влияет на продажи и помогает сделать затраты на продвижение прозрачными, эффективными и аргументированными.`],шаги:[{имя:`Определение KPI`,текст:`В начале пути мы фиксируем, какие результаты хотел бы получить заказчик, какие параметры рекламы важны для анализа.`},{имя:`Аналитика`,текст:`Разрабатываем Customer Journey Map, фиксируем этапы движения покупателя от рекламы до покупки.`},{имя:`Техническая часть`,текст:`Получаем данные о блогерах через платформу Follower AI, интегрируем её с CRM-системой.`},{имя:`Отчет`,текст:`Предоставляем отчет с четкими данными: например, “блогер X дал на 30% больше продаж, а аудитория блогера Y чаще покидала сайт, оставляя товары в корзине”. Также рекомендуем пути для улучшения.`}]}]},d={имя:`Медиабаинг и медиапланирование`,лид:`Управляем закупками рекламы лидеров мнений в России и на международном уровне.`,значок:`/media/lider/2.svg`,направление:`lider`,титул:`Медиабаинг и медиапланирование - Social Stars`,описание:null,вкладка:4,блоки:[{вид:`beforemore`,имя:`Что мы делаем?`,слева:[{вид:`абзац`,строки:[`Имеем собственную базу более 2000 лидеров мнений по различным направлениям: лайфстайл, спорт, автомобили, бьюти, культура, общественная деятельность, бизнес и другие.`]},{вид:`абзац`,строки:[`• Выстраиваем для заказчиков долгосрочные кампании, работая с блогерами.`,`• Закупаем рекламу на основе лучших условий и высокоэффективных цен.`,`• Используем подход, исключающий «перегретую» аудиторию и излишние коммерческие размещения.`]},{вид:`абзац`,строки:[`В 2015 году в партнёрстве с Тимуром Бекмамбетовым и Сашей Спилберг мы основали первое блогерское агентство в России, что позволило выстроить профессиональные отношения с лидерами мнений и эффективно вести переговоры.`]}],справа:[{вид:`абзац`,строки:[`Медиапланирование позволяет:`]},{вид:`абзац`,строки:[`• Оптимизировать затраты на рекламу, сохраняя высокую конверсию.`,`• Исключить рекламу конкурентов.`,`• Повысить доверие целевой аудитории.`]},{вид:`абзац`,строки:[`Медиабаинг - осуществление договоренностей, чтобы блогер предоставлял заказчику наиболее выгодные условия с точки зрения интеграции продукта и сотрудничества. Сюда можно включить ситуации, когда лидер мнений готов пойти на существенные ценовые уступки в результате лояльности к бренду заказчика, либо же проявить дополнительные усилия в ходе разработки креативной интеграции.`]}]},{вид:`verticals`,имя:`Особенности медиабаинга Social Stars:`,карточки:[{имя:null,значок:`/media/lider/l1.svg`,строки:[`Оптимизация затрат: работа напрямую с блогерами позволяет снижать стоимость размещения на 20–30 %.`]},{имя:null,значок:`/media/lider/l1.svg`,строки:[`Фильтрация лидеров мнений: исключаем участников, не имеющих влияния и доверия.`]},{имя:null,значок:`/media/lider/l1.svg`,строки:[`Долгосрочная выгода: сокращение затрат на охват, улучшение аналитики и повышение KPI.`]}]},{вид:`history`,имя:`Инструменты для реализации:`,текст:[`Выступаем на стороне заказчика, обеспечивая его интересы в переговорах с блогерами, сокращая бюджеты и подбирая лучшие варианты из числа новых лиц Интернета.`],шаги:[{имя:`Составление брифа`,текст:`Заказчик определяет приоритеты (предпочтительные блогеры, аудитория).`},{имя:`Подбор блогеров`,текст:`Используем платформу Follower AI для поиска подходящих лидеров мнений с учётом пересечения аудиторий.`},{имя:`Учитываем интересы блогера`,текст:`Подстраиваем представление бренда так, чтобы блогеры искренне рекомендовали продукт.`},{имя:`Полный цикл`,текст:`Согласуем сметы, разрабатываем креативные концепции, обеспечиваем регулярность размещений.`}]}]},f={имя:`Follower AI`,лид:`Разработали собственную “умную” платформу для исследования лидеров мнений и Телеграм-каналов.`,значок:null,направление:`market`,титул:`Follower AI – исследование телеграм-каналов от Social Stars`,описание:`Разработали собственную “умную” платформу для исследования лидеров мнений и Телеграм-каналов. Подробнее на сайте.`,вкладка:3,блоки:[{вид:`beforemore`,имя:`Что мы делаем?`,слева:[{вид:`абзац`,строки:[`Помогаем проводить измерения аудитории блогеров, Телеграм-каналов, предоставляем статистику, которую нельзя определить через стандартные счетчики платформ.`,`С развитием социальных сетей все большую роль в маркетинге играет big data. Креатив опирается на цифры, а продвижение становится более технологичным. Мы исследуем объекты более чем по тридцати различным параметрам — от социально-демографических характеристик, культурных аспектов, до интересов, предпочтений и даже любимых мест.`,`Follower AI работает не только для российского рынка, но наши алгоритмы использовались в проектах на Ближнем Востоке и в Китае.`]}],справа:[]},{вид:`more`,имя:`Преимущества`,колонки:[`Публикуем исследования в РБК, Gazeta.Ru.`,`Делаем аналитику для правительства.`,`Быстрые сроки.`,`Платформа №1 в России.`]},{вид:`verticals`,имя:`Наш подход:`,карточки:[{имя:`Целевая Аудитория`,значок:`/media/promotion/7.svg`,строки:[`Определяем Целевую Аудиторию проекта. Собираем данные этих людей - телефоны, профили и так далее. Формируем фокус-группу.`]},{имя:`Отсев`,значок:`/media/promotion/5.svg`,строки:[`Через Follower AI видим на какие сообщества и лидеров мнений подписаны представители ЦА. Включаем ручной контроль.`]},{имя:`Пересечения`,значок:`/media/promotion/4.svg`,строки:[`Выбираем лучших блогеров по цене, исключаем из списка тех, у кого похожий подписчик. Программа автоматически показывает эти данные.`]},{имя:`ТГ-каналы`,значок:`/media/promotion/8.svg`,строки:[`Умеем видеть аудиторию Телеграм-каналов.`]}]},{вид:`statistika`,имя:`Цифры`,показатели:[{кадр:null,число:`3`,черта:!0,подпись:`В три раза увеличили охват блогеров в кейсе “Московской Недели Интерьера и Дизайна” через первое применение Follower AI.`},{кадр:null,число:`250%`,черта:!0,подпись:`Снижение затрат на единицу OTS в рамках блогерской кампании при использовании точечных метрик.`},{кадр:null,число:`2%`,черта:!0,подпись:`Допустимая погрешность статистических измерений.`},{кадр:null,число:`600%`,черта:!1,подпись:`Рост скорости процессов, которые необходимо раньше было анализировать вручную.`}]}]},p={имя:`Автоматизация социальных сетей`,лид:`Увеличиваем активность подписчиков во всех социальных сетях, используя технические решения.`,значок:null,направление:`market`,титул:`Автоматизация социальных сетей – цены в Social Stars`,описание:`Увеличиваем активность подписчиков во всех социальных сетях, используя технические решения.`,вкладка:3,блоки:[{вид:`beforemore`,имя:`Что мы делаем?`,слева:[{вид:`абзац`,строки:[`Крупные бренды и компании часто используют дополнительные инструменты для увеличения статистики, чтобы привлечь своих потребителей. Речь идет о росте подписчиков, лайков, просмотров и других параметров. Часто это сложно синхронно повышать, для чего мы применяем автоматизацию.`]},{вид:`абзац`,строки:[`Мы создаем решения, позволяющие каждому вышедшему посту в Instagram, Telegram, ВКонтакте, Дзене или другой социальной сети мгновенно начинать продвижение сразу после публикации.`]}],справа:[]},{вид:`beforemore`,имя:`Что мы делаем?`,слева:[{вид:`абзац`,строки:[`Крупные бренды и компании часто используют дополнительные инструменты для увеличения статистики, чтобы привлечь своих потребителей. Речь идет о росте подписчиков, лайков, просмотров и других параметров. Часто это сложно синхронно повышать, для чего мы применяем автоматизацию.`]},{вид:`абзац`,строки:[`Мы создаем решения, позволяющие каждому вышедшему посту в Instagram, Telegram, ВКонтакте, Дзене или другой социальной сети мгновенно начинать продвижение сразу после публикации.`]}],справа:[]},{вид:`more`,имя:`Преимущества`,колонки:[`Собственные разработки.`,`Работаем в любых социальных сетях.`,`Выполняем работу быстро.`,`Обучаем ваших сотрудников.`]},{вид:`verticals`,имя:`Наш подход:`,карточки:[{имя:`Технические решения`,значок:`/media/promotion/1.svg`,строки:[`Выделяем специалиста под проект, проводим аналитику текущих задач, составляем смету.`]},{имя:`Скорость`,значок:`/media/promotion/9.svg`,строки:[`Работаем по принципу MVP — минимально функционирующий продукт предоставляется в кратчайшие сроки, чтобы запустить необходимые процессы.`]},{имя:`Интеграция`,значок:`/media/promotion/4.svg`,строки:[`Создаем решения, позволяющие заказчику управлять процессом через нажатие двух кнопок.`]},{имя:`Безопасность`,значок:`/media/promotion/6.svg`,строки:[`Результат наших действий полностью соответствует политике социальных сетей, так как платформа не может определить внешнее вмешательство.`]}]},{вид:`statistika`,имя:`Цифры`,показатели:[{кадр:null,число:`X3`,черта:!0,подпись:`сокращение времени на выполнение базовых действий.`},{кадр:null,число:`160%`,черта:!0,подпись:`ускорение продвижение контента.`},{кадр:null,число:`29%`,черта:!1,подпись:`снижение бюджетов на выполнение KPI.`}]}]},m={имя:`Телеграм`,лид:`Лидеры в РФ по созданию Телеграм-каналов под ключ для государственных структур и крупного бизнеса. Реклама с лидерами мнений, работа с TG Ads.`,значок:null,направление:`market`,титул:`Создание и продвижение каналов в Телеграм (Telegram) – Social Stars`,описание:`Лидеры в РФ по созданию Телеграм-каналов под ключ для государственных структур и крупного бизнеса. Реклама с лидерами мнений, работа с TG Ads.`,вкладка:2,блоки:[{вид:`beforemore`,имя:`Что мы делаем?`,слева:[{вид:`абзац`,строки:[`Выстраиваем информационную политику для коммерческих заказчиков и официальных организаций в новых медиа. Компания Social Stars обладает большой экспертизой в области работы с Телеграм-каналами. Среди наших клиентов: “Мостуризм”, SKOLKOVO, Правительство Москвы, Avito и многие другие заказчики. Соблюдаем все необходимые стандарты контент-политики, в короткие сроки решаем любые задачи, связанные с KPI, привлекаем опытных отраслевых и лайфстайл-журналистов для ведения проектов.`]},{вид:`абзац`,строки:[`При помощи наших ресурсов создана одна из крупнейших Телеграм-сетей в Москве, составляющая более 2,5 миллионов подписчиков. Также более 50 каналов из нашей базы для закупок входят в рейтинг самых значимых информационных площадок в России по версии аналитических рейтингов. При помощи тесных отношений с администраторами и оптимизации креатива оптимизируем цены на размещение на 20-30%, что позволяет экономить нашим клиентам миллионы бюджета.`]}],справа:[]},{вид:`more`,имя:`Преимущества`,колонки:[`Продвигаем каналы в тематиках b2с и b2b.`,`Собственная сеть с охватом более 2 млн человек в день.`,`Создаем каналы с 0.`,`Лучшие цены на рынке на закупку.`]},{вид:`verticals`,имя:`Наш подход:`,карточки:[{имя:`Быстрые сроки`,значок:`/media/promotion/1.svg`,строки:[`Можем создать новый канал на 500 000 подписчиков за 1-2 месяца в зависимости от брифа и задачи.`]},{имя:`Работаем с журналистами`,значок:`/media/promotion/3.svg`,строки:[`Основатели Social Stars имеют многолетний опыт работы в федеральных СМИ, поэтому подключаем к проектам лучших авторов на рынке.`]},{имя:`Ценовая политика`,значок:`/media/promotion/4.svg`,строки:[`Имеем хорошие отношения с целым рядом важных площадок - от Александра Цыпкина и Mash, до Пул№3 и Политджойстик. Цена будет ниже через нас, можете сравнить написав в один из каналов нашей подборки.`]},{имя:`Анонимность`,значок:`/media/promotion/6.svg`,строки:[`Специализируемся на решении антикризисных задач, поэтому наши решения отличаются конфиденциальностью и нелинейностью.`]}]},{вид:`statistika`,имя:`Цифры`,показатели:[{кадр:null,число:`30%`,черта:!0,подпись:`Средняя экономия бюджета заказчика на больших проектах.`},{кадр:null,число:`1500`,черта:!0,подпись:`Осуществлено коммерческих размещений за 2024 год.`},{кадр:null,число:`5000`,черта:!1,подпись:`каналов с аудиторией свыше 50 000 подписчиков в нашей базе.`}]}]},h={lichnyi_brend:e,pr:t,monitoring_i_analitika:n,orm:r,serm:i,antikrizis:a,udalenie_informacii:o,issledovanie:s,kreativnye_integracii:c,brand_lift:l,sales_lift:u,"sozdanie-blogera":{имя:`Создание блогера с нуля`,лид:`В современной цифровой среде личный блог перестал быть просто онлайн-дневником и превратился в мощный стратегический актив. Для эксперта это лучший способ продемонстрировать свою компетентность и построить персональный блог. Для бизнеса – это эффективный инструмент для привлечения органического трафика, повышения узнаваемости и формирование пула лояльных клиентов. Однако создание блогера с нуля – это сложный и многогранный процесс, и успешное создание блога зависит не столько от одной блестящей идеи, сколько от системного подхода. Многие энтузиасты, решая начинать самостоятельно с нуля, сталкиваются с выгоранием и отсутствием результата, ведь 55% авторов не получают от своего блога никакого дохода. Мы предлагаем профессиональную помощь в создании блога, чтобы ваш проект стал успешным и прибыльным.`,значок:`/media/lider/6.svg`,направление:`lider`,титул:`Создание блогера с нуля - Social Stars`,описание:null,вкладка:4,блоки:[]},"eksklyuzivnye-blogery":{имя:`Эксклюзивные блогеры`,лид:`Располагаем собственным пулом лидеров мнений с особыми условиями и ценами.`,значок:`/media/lider/7.svg`,направление:`lider`,титул:`Эксклюзивные блогеры – цены интеграций в агентстве Social Stars`,описание:`Располагаем собственным пулом лидеров мнений с особыми условиями и ценами. Интерграции для брендов под ключ от агентства Social Stars.`,вкладка:4,блоки:[{вид:`beforemore`,имя:`Что мы делаем?`,слева:[{вид:`абзац`,строки:[`В 2014 году Social Stars создали первое блогерское СМИ в России. С тех пор вокруг нашей компании накопилось много успешных кейсов, появились интересные знакомства. В значительной степени наши отношения с блогерами строятся на взаимовыгодном партнерстве и дружбе. Это является гарантией того, что каждый наш заказчик получит не только лучшие цены, но и особый подход, выраженный в заинтересованности в результате.`]}],справа:[{вид:`абзац`,строки:[`Среди лидеров мнений, которые предоставляют нам самые лучшие цены - Николай Соболев, Алексей Столяров, Саша Спилберг, Амиран Сардаров, Дмитрий Гордей, Сергей Жуков, Гуфи Медалин, Милана Тюльпанова, Николай Басков и многие другие. Вы всегда можете проверить эту информацию, просто сравнив наше предложение с другими агентами.`]},{вид:`абзац`,строки:[`Наше агентство создало институт Исследования лидеров мнений, что является мощной точкой притяжения для блогеров, которые сами хотят сотрудничать с нами.`]}]},{вид:`verticals`,имя:`Почему с нами выгодно работать?`,карточки:[{имя:null,значок:`/media/lider/l1.svg`,строки:[`Мы дружим с блогерами, поэтому всегда можем спросить у них совет, скидку или дать честный ответ, насколько эффективно будет рекламировать товар/услугу.`]},{имя:null,значок:`/media/lider/l1.svg`,строки:[`Приглашаем лидеров мнений участвовать в креативном процессе, что дает беспрецедентные возможности для установления коммуникации с аудиторией.`]},{имя:null,значок:`/media/lider/l1.svg`,строки:[`Готовы аргументировать выбор того или иного лидера мнений не только на языке контента и креатива, но и в цифрах.`]}]},{вид:`history`,имя:`Инструменты для реализации:`,текст:[`Создание блогеров - творческий процесс, но его результат можно предсказать и оптимизировать, если задействовать лучший опыт предыдущих проектов и аналитику рынка.`],шаги:[{имя:`Заполнение брифа`,текст:`В начале любого проекта мы просим заказчика заполнить бриф, в котором указываем необходимые параметры, сопоставляем ЦА, после чего предлагаем лучших блогеров, которые есть в нашем пуле.`},{имя:`Креативность`,текст:`Приглашаем блогеров самостоятельно придумать рекламу для клиента - заинтересованный лидер мнений увеличивает эффективность размещения в три-четыре раза.`},{имя:`Амбассадоры`,текст:`Помогаем брендам и блогерам знакомиться для заключения долгосрочных партнерских стратегий с целью выгоды.`},{имя:`Менеджмент`,текст:`Четко следим за результатами блогеров, имеем возможность быстро связаться и проконтролировать процесс в случае деликатных моментов.`}]}]},mediabaing_i_mediaplanirovanie:d,"motivirovanny-trafik":{имя:`Мотивированный трафик`,лид:`Управляем большими объемами интернет-трафика, улучшая результаты рекламных кампаний.`,значок:null,направление:`market`,титул:`Мотивированный трафик – цены в Social Stars`,описание:`Управляем большими объемами интернет-трафика, улучшая результаты рекламных кампаний. Агентство Social Stars.`,вкладка:3,блоки:[{вид:`beforemore`,имя:`Что мы делаем?`,слева:[{вид:`абзац`,строки:[`Мотивированный трафик в рекламе — это стратегически организованный поток пользователей, которые взаимодействуют с вашим сайтом или приложением в обмен на эксклюзивные бонусы, уникальные предложения или доступ к специальному контенту. Такой подход помогает быстро увеличить количество просмотров, социальную активность, повысить посещаемость веб-ресурса и сформировать импульс для дальнейшего роста.`]},{вид:`абзац`,строки:[`Мы анализируем эффективность мотивированного трафика, оцениваем его влияние на ключевые показатели бизнеса и формируем долгосрочные стратегии для достижения максимальных результатов.`]},{вид:`абзац`,строки:[`Обрабатываем большие объемы трафика — от тысяч до миллионов пользователей.`]}],справа:[]},{вид:`more`,имя:`Преимущества`,колонки:[`Опыт работы с государственными заказчиками.`,`Возможность реализации проектов любого масштаба.`,`Гарантия конфиденциальности (работаем через NDA).`,`Лучшая цена за CPV, CPC, CPF.`]},{вид:`verticals`,имя:`Наш подход:`,карточки:[{имя:`Аудит`,значок:`/media/icons/verticals-community.svg`,строки:[`Проводим детальный анализ задачи, определяем, какой метод или инструмент обеспечит максимальную эффективность и поможет в достижении бизнес-целей.`]},{имя:`Технология`,значок:`/media/icons/star.svg`,строки:[`Привлекаем специализированную команду для реализации технических решений. Айти-кластер действует совместно с маркетологами для достижения поставленных целей.`]},{имя:`Сроки`,значок:`/media/icons/clock.svg`,строки:[`Предлагаем несколько вариантов реализации проекта, учитывая желаемую скорость и бюджет заказчика.`]},{имя:`Безопасность`,значок:`/media/icons/trust.svg`,строки:[`Не используем “мусорную” аудиторию или искусственные накрутки. Все наши решения нацелены на долгосрочную пользу и уникальны.`]}]},{вид:`statistika`,имя:`Цифры`,показатели:[{кадр:null,число:`7`,черта:!0,подпись:`В семь раз сокращается средняя стоимость результата в рекламных кампаниях.`},{кадр:null,число:`27`,черта:!0,подпись:`Количество ключевых параметров, которые мы отслеживаем (просмотры, клики, охваты, лайки и др.).`},{кадр:null,число:`48%`,черта:!0,подпись:`Рост органического трафика после внедрения новых инструментов.`},{кадр:null,число:`200%`,черта:!1,подпись:`Увеличение скорости выполнения проектов благодаря оптимизации процессов.`}]}]},"optimizaciya-kpi":{имя:`Оптимизация KPI`,лид:`Помогаем достигать KPI для крупных государственных и коммерческих проектов. Работая с агентствами, предоставляем комплексные и нестандартные решения.`,значок:null,направление:`market`,титул:`Оптимизация KPI - Social Stars`,описание:null,вкладка:5,блоки:[{вид:`beforemore`,имя:`Что мы делаем?`,слева:[{вид:`абзац`,строки:[`Вам нужно выполнить KPI в рамках тендера, но вы сталкиваетесь с проблемами реализации или высокими затратами? Мы знаем, как сократить расходы с помощью надежных, проверенных инструментов. Все проекты ведутся конфиденциально.`]},{вид:`абзац`,строки:[`Работая над проектами, мы не просто сокращаем расходы, но и помогаем выстроить эффективную стратегию достижения KPI. Мы превратили управление KPI в точную науку.`]}],справа:[]},{вид:`more`,имя:`Преимущества`,колонки:[`Полная безопасность и отсутствие рисков.`,`Эффективные решения для сложных ситуаций.`,`Значительное сокращение бюджета.`,`Экспертиза в различных отраслях.`]},{вид:`verticals`,имя:`Наш подход:`,карточки:[{имя:`Аналитика`,значок:`/media/promotion/4.svg`,строки:[`Тщательно анализируем рекламные кампании, чтобы выявить неэффективные траты и оптимизировать бюджет.`]},{имя:`Технологическая сторона`,значок:`/media/promotion/5.svg`,строки:[`Обладаем собственным штатом программистов, способных реализовать сложные технические задачи.`]},{имя:`Отдел маркетинга`,значок:`/media/promotion/2.svg`,строки:[`Наша команда с опытом более 10 лет помогает компаниям и блогерам достигать KPI в различных проектах.`]},{имя:`Безопасность`,значок:`/media/promotion/6.svg`,строки:[`Гарантируем конфиденциальность через NDA, обеспечиваем индивидуальный подход к каждому заказчику.`]}]},{вид:`statistika`,имя:`Цифры`,показатели:[{кадр:null,число:`5`,черта:!0,подпись:`В пять раз сокращаются издержки на ключевые показатели (просмотры, лайки, подписчики).`},{кадр:null,число:`27`,черта:!0,подпись:`Количество параметров (лайки, просмотры, охваты, визиты, клики), с которыми работает наша команда.`},{кадр:null,число:`45%`,черта:!0,подпись:`Увеличение эффективности рекламных кампаний после оптимизации KPI.`},{кадр:null,число:`60%`,черта:!1,подпись:`Ускорение достижения вирусного роста.`}]}]},follower_ai:f,avtomatizaciya_social_setey:p,"razrabotka_chat-botov":{имя:`Разработка чат-ботов`,лид:`Создаём виртуальных помощников для бизнеса и взаимодействия с клиентами.`,значок:null,направление:`market`,титул:`Разработка чат-ботов – цены в Social Stars`,описание:`Создаём виртуальных помощников для бизнеса и взаимодействия с клиентами. Эффективные чат-боты по выгодной цене.`,вкладка:5,блоки:[{вид:`beforemore`,имя:`Что мы делаем?`,слева:[{вид:`абзац`,строки:[`За последние несколько лет искусственный интеллект и программное обеспечение сделали огромный шаг вперёд. Применение технологий AI в маркетинге становится обязательным. Инновации помогают в несколько раз увеличить эффективность взаимодействия с потребителем.`]},{вид:`абзац`,строки:[`Боты:`,`• Никогда не устают и работают круглосуточно.`,`• Эффективно решают задачи и обучаются в процессе работы.`,`• Не грубят, имеют встроенный эмоциональный интеллект.`]},{вид:`абзац`,строки:[`Внедрение «умных» решений помогает оптимизировать расходы на взаимодействие с клиентами и снижает затраты на персонал.`]}],справа:[]},{вид:`more`,имя:`Преимущества`,колонки:[`Свой штат программистов.`,`Интеграция с сайтом.`,`Создание сложных чат-ботов.`,`Обучение сотрудников.`]},{вид:`verticals`,имя:`Наш подход:`,карточки:[{имя:`Решение проблем`,значок:`/media/promotion/1.svg`,строки:[`Мы строим каждый проект на основе конкретных задач клиента, опираясь на внутреннюю аналитику и собственный опыт.`]},{имя:`Разработка`,значок:`/media/promotion/3.svg`,строки:[`Согласовываем с заказчиком план, приступаем к созданию структуры. Внедряем решения, интегрируем их с сайтом, социальными сетями, оптимизируем работу с площадками.`]},{имя:`Big data`,значок:`/media/promotion/4.svg`,строки:[`Мы обучаем ботов взаимодействовать с клиентами, собирать и анализировать информацию, чтобы заказчик мог использовать данные для достижения коммерческих целей.`]},{имя:`Поддержка`,значок:`/media/promotion/6.svg`,строки:[`Фокусируемся на обработке обратной связи от потребителей, улучшаем решения в зависимости от пожеланий и дополнений клиентов.`]}]},{вид:`statistika`,имя:`Цифры`,показатели:[{кадр:null,число:`68%`,черта:!0,подпись:`Рост вовлечённости клиентов при использовании автоматических воронок и интеллектуальных решений маркетинга.`},{кадр:null,число:`2`,черта:!0,подпись:`Столько менеджеров может заменить хороший бот-помощник.`},{кадр:null,число:`75%`,черта:!1,подпись:`Увеличение конверсии рекламы при интеграции автоматических систем.`}]}]},telegram:m,"работа-с-алгоритмами-соцсетей-цены":{имя:`Работа с алгоритмами`,лид:`Сформировали науку изучения внутренних инструментов и алгоритмов социальных сетей и платформ.`,титул:`Работа с алгоритмами - Social Stars`,описание:`Органическое продвижение в социальных сетях, работа с алгоритмами. PR-агентство Social Stars.`,блоки:[{уровень:`h2`,имя:`Что мы делаем?`,текст:`Сегодня любая платформа или сервис — это не просто хранилище фото, видео или текстов, а инструмент для продвижения. Архитектура социальных сетей устроена так, что креативный контент продвигается автоматически, а рекламный — намеренно ограничивается. Но кто решает, какой контент считать “хорошим”? За алгоритмами продвижения и их результатами стоят определенные показатели, которые встроены в каждую из существующих платформ. Мы ставим своей целью не борьбу с социальной сетью, а помощь качественным творческим продуктам в достижении популярности. Наши технологии помогают усилить значимость идей, минимизируя влияние платформ на конкурентную честность. Таким образом, мы не только поддерживаем справедливость, но и даем брендам возможность расти в сложных условиях рынка.`},{уровень:`h2`,имя:`Преимущества`,текст:null},{уровень:`h1`,имя:`1`,текст:`Многолетний опыт работы в социальных сетях с 2011 года.`},{уровень:`h1`,имя:`2`,текст:`Разработка первых приложений для работы с платформой Instagram*.`},{уровень:`h1`,имя:`3`,текст:`Использование авторского программного обеспечения.`},{уровень:`h1`,имя:`4`,текст:`Глубокое знание допустимых ограничений алгоритмов.`},{уровень:`h2`,имя:`Наш подход:`,текст:null},{уровень:`h3`,имя:`Целевая Аудитория`,текст:`Мы определяем целевую аудиторию проекта, собирая ключевые данные о пользователях: контакты, профили и другую информацию. На основе этих данных формируем фокус-группы для эффективного анализа и продвижения.`},{уровень:`h3`,имя:`Отсев`,текст:`С помощью Follower AI анализируем, на какие сообщества и лидеров мнений подписаны представители целевой аудитории. Дополнительно включаем ручной контроль для исключения ошибок и неточностей.`},{уровень:`h3`,имя:`Пересечения`,текст:`Идентифицируем лучших блогеров по соотношению цены и эффективности, исключая тех, чья аудитория имеет значительное пересечение с другими. Программа автоматически предоставляет точные аналитические данные.`},{уровень:`h3`,имя:`ТГ-каналы`,текст:`Используем технологии для детального анализа аудитории Telegram-каналов, что позволяет выявлять ключевые предпочтения и интересы пользователей.`},{уровень:`h2`,имя:`Цифры`,текст:null},{уровень:`h3`,имя:`35%`,текст:`Рост среднестатистических показателей вирусного охвата в первую неделю запуска проекта.`},{уровень:`h3`,имя:`2`,текст:`Снижение стоимости за результат за счет оптимизации кампаний.`},{уровень:`h3`,имя:`65%`,текст:`Сокращение затрат на достижение необходимых метрик, включая охваты, лайки и клики.`}],вкладка:0}};export{a as antikrizis,p as avtomatizaciya_social_setey,l as brand_lift,h as default,f as follower_ai,s as issledovanie,c as kreativnye_integracii,e as lichnyi_brend,d as mediabaing_i_mediaplanirovanie,n as monitoring_i_analitika,r as orm,t as pr,u as sales_lift,i as serm,m as telegram,o as udalenie_informacii};